alter table public.referrals drop constraint referrals_code_key;
create unique index referrals_pair_unique on public.referrals(referrer_id,referred_id) where referred_id is not null;
create table public.referral_codes(referrer_id uuid primary key references auth.users(id) on delete cascade,code text not null unique check(length(code) between 8 and 32),enabled boolean not null default true,created_at timestamptz not null default now());
alter table public.referral_codes enable row level security;create policy referral_codes_owner on public.referral_codes for all to authenticated using(referrer_id=(select auth.uid())) with check(referrer_id=(select auth.uid()));grant select,insert,update on public.referral_codes to authenticated;
create or replace function public.claim_referral(p_code text) returns void language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());referrer uuid;begin if uid is null then raise exception 'AUTHENTICATION_REQUIRED';end if;select referrer_id into referrer from public.referral_codes where code=p_code and enabled;if referrer is null or referrer=uid then return;end if;insert into public.referrals(referrer_id,referred_id,code,status) values(referrer,uid,p_code,'signed_up') on conflict(referrer_id,referred_id) where referred_id is not null do nothing;end $$;
revoke all on function public.claim_referral(text) from public,anon;grant execute on function public.claim_referral(text) to authenticated;
